import { readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const repositoryRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const generatedDirectory = path.join(repositoryRoot, 'src/generated/local-archive-core');
const wasmPath = path.join(generatedDirectory, 'local_archive_core_bg.wasm');
const modulePath = path.join(generatedDirectory, 'local_archive_core_wasm.ts');
const wasmBytes = await readFile(wasmPath);
const source = [
  '// Generated by scripts/embed-rust-wasm.mjs. Do not edit by hand.',
  `export const LOCAL_ARCHIVE_CORE_WASM_BASE64 = '${wasmBytes.toString('base64')}';`,
  '',
].join('\n');

await writeFile(modulePath, source, 'utf8');
